'use strict';

const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const entry = path.join(root, 'parser', 'src', 'browser_api.js');
const output = path.join(root, 'browser', 'parser-bundle.js');
const modules = new Map();
const requirePattern = /require\((['"])(\.\.?\/[^'"]+)\1\)/g;

function moduleId(filePath) {
  return path.relative(root, filePath).split(path.sep).join('/');
}

function resolveRelative(fromFile, request) {
  const base = path.resolve(path.dirname(fromFile), request);
  const candidate = path.extname(base) ? base : `${base}.js`;
  if (!candidate.startsWith(`${root}${path.sep}`)) {
    throw new Error(`Browser bundle dependency escapes repository root: ${request}`);
  }
  if (!fs.existsSync(candidate)) {
    throw new Error(`Browser bundle dependency not found: ${request} from ${moduleId(fromFile)}`);
  }
  return candidate;
}

function collect(filePath) {
  const id = moduleId(filePath);
  if (modules.has(id)) return;
  const source = fs.readFileSync(filePath, 'utf8');
  modules.set(id, source);
  for (const match of source.matchAll(requirePattern)) {
    collect(resolveRelative(filePath, match[2]));
  }
}

function indent(source, spaces) {
  const prefix = ' '.repeat(spaces);
  return source.split('\n').map((line) => `${prefix}${line}`).join('\n');
}

collect(entry);
const registry = Array.from(modules.entries())
  .sort(([left], [right]) => left.localeCompare(right))
  .map(([id, source]) => `    ${JSON.stringify(id)}: function(module, exports, require) {\n${indent(source, 6)}\n    }`)
  .join(',\n');

const bundle = `/* Generated by scripts/build_browser_parser_bundle.js. Do not edit directly. */
(function attachBosangParser(global) {
  'use strict';
  const modules = {
${registry}
  };
  const cache = Object.create(null);

  function normalizePath(value) {
    const outputParts = [];
    value.split('/').forEach((part) => {
      if (!part || part === '.') return;
      if (part === '..') outputParts.pop();
      else outputParts.push(part);
    });
    return outputParts.join('/');
  }

  function resolve(fromId, request) {
    if (!request.startsWith('.')) throw new Error('Browser parser blocks non-relative dependency: ' + request);
    const base = fromId.split('/').slice(0, -1).join('/');
    const resolved = normalizePath(base + '/' + request);
    return resolved.endsWith('.js') ? resolved : resolved + '.js';
  }

  function load(id) {
    if (cache[id]) return cache[id].exports;
    const factory = modules[id];
    if (!factory) throw new Error('Browser parser module not found: ' + id);
    const module = { exports: {} };
    cache[id] = module;
    factory(module, module.exports, function localRequire(request) {
      return load(resolve(id, request));
    });
    return module.exports;
  }

  global.BosangParser = load(${JSON.stringify(moduleId(entry))});
})(typeof window !== 'undefined' ? window : globalThis);
`;

fs.mkdirSync(path.dirname(output), { recursive: true });
fs.writeFileSync(output, bundle, 'utf8');
process.stdout.write(`browser parser bundle: ${moduleId(output)} (${Buffer.byteLength(bundle)} bytes)\n`);
